import subprocess, os
def handle(query, state):
    host = (query.get("host") or [""])[0]
    if not host:
        return 200, {"Content-Type": "text/plain"}, "Usage: ?host=<hostname>"
    env = dict(os.environ)
    env["APP_FLAG"] = state["flag"]
    try:
        result = subprocess.check_output(
            "ping -c 1 " + host,
            shell=True,
            stderr=subprocess.STDOUT,
            env=env,
            timeout=5
        )
        return 200, {"Content-Type": "text/plain"}, result.decode("utf-8", errors="replace")
    except subprocess.CalledProcessError as e:
        return 200, {"Content-Type": "text/plain"}, e.output.decode("utf-8", errors="replace")
    except Exception as e:
        return 500, {"Content-Type": "text/plain"}, str(e)
